```PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?biggestCity ?northCountry ?mississippiState WHERE {
  {
    # 5 biggest cities in USA
    {
      SELECT ?biggestCity (MAX(?yr) AS ?recent_yr) ?populationNumber
      WHERE {
        ns:m.09c7w0 ns:location.location.contains ?biggestCity .
        ?biggestCity ns:common.topic.notable_types ns:m.01m9 . # City/Town/Village
        ?biggestCity ns:location.statistical_region.population ?population .
        ?population ns:measurement_unit.dated_integer.number ?populationNumber .
        ?population ns:measurement_unit.dated_integer.year ?yr .
      }
      GROUP BY ?biggestCity ?populationNumber
      ORDER BY DESC(xsd:integer(?populationNumber))
      LIMIT 5
    }
  }
  UNION
  {
    # country to the north of USA
    ns:m.09c7w0 ns:location.location.adjoin_s ?adjacency .
    ?adjacency ns:location.adjoining_relationship.adjoins ?northCountry .
    ns:m.09c7w0 ns:location.location.geolocation ?geoUSA .
    ?geoUSA ns:location.geocode.latitude ?latUSA .
    ?northCountry ns:location.location.geolocation ?geoAdjCountry .
    ?geoAdjCountry ns:location.geocode.latitude ?latAdjCountry .
    FILTER(xsd:float(?latAdjCountry) > xsd:float(?latUSA))
  }
  UNION
  {
    # states Mississippi river passes through
    ns:m.04yf_ ns:location.location.partially_containedby ?mississippiState .
    ?mississippiState ns:base.biblioness.bibs_location.loc_type ?stateType .
    FILTER(str(?stateType) = "State")
    FILTER(?mississippiState != ns:m.04yf_)
  }
}
LIMIT 5
