      }
      ?war ns:common.topic.notable_types ns:m.02h76fz ;  # Military Conflict
           ns:time.event.start_date ?warStart ;
           ns:time.event.end_date ?warEnd ;
           ns:military.military_conflict.combatants ?combatant .
      ?combatant ns:military.military_combatant_group.combatants ns:m.09c7w0 . # United States
      FILTER (?warEnd <= ?pto && ?warStart >= ?pfrom)
    } LIMIT 1
  }
  # Query for Abraham Lincoln's place of birth (town)
  {
    SELECT DISTINCT ?birthPlace WHERE {
      ns:m.0gzh ns:people.person.place_of_birth ?birthPlace .
      ?birthPlace ns:common.topic.notable_types ns:m.01m9 .  # Town
