  # Query for the year when Abraham Lincoln was elected president
  {
    SELECT DISTINCT ?electionYear WHERE {
      ?election ns:government.election.winner ns:m.0gzh ;
                ns:government.election.office ns:m.060d2 ; # President of the United States
                ns:government.election.election_year ?electionYear .
