PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?team
WHERE {
  VALUES ?player { ns:m.099vgz ns:m.01zt27 } 

  FILTER (?player = ns:m.099vgz || ?player = ns:m.01zt27)

  # For Sergio Aguero (ns:m.099vgz), get the teams
  {
    FILTER(?player = ns:m.099vgz)
    ?player ns:sports.pro_athlete.teams ?roster .
    ?roster ns:sports.sports_team_roster.team ?team .

    # For question 1: team before Man City (ns:m.01634x)
    OPTIONAL {
      ?roster ns:sports.sports_team_roster.from ?from .
      ?roster ns:sports.sports_team_roster.to ?to .
    }
    FILTER (
      ( 
        # For "before Man City"
        EXISTS { ?roster ns:sports.sports_team_roster.to ?to . FILTER (?team != ns:m.01634x) }
        &&  
        EXISTS {
          ?player ns:sports.pro_athlete.teams ?mcroster .
          ?mcroster ns:sports.sports_team_roster.team ns:m.01634x .
          ?mcroster ns:sports.sports_team_roster.from ?mcfrom .
          ?roster ns:sports.sports_team_roster.to ?roto .
          FILTER(xsd:dateTime(?roto) <= xsd:dateTime(?mcfrom))
        }
      )
      || 
      # For current team (question 2)
      (!EXISTS {?roster ns:sports.sports_team_roster.to ?to} || ( ?to >= NOW () ))
    )
  }
  UNION
