```PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?religion ?birthTown ?war
WHERE {
  # Religion of Mary Todd Lincoln
  ns:m.01ypl0 ns:people.person.religion ?religion .

  # Birth town of Abe Lincoln
  ns:m.0gzh ns:people.person.place_of_birth ?birthTown .
  ?birthTown ns:common.topic.notable_types ns:m.01m9 .

  # War during which Abraham Lincoln was president
  {
    SELECT ?pfrom ?pto
    WHERE {
      ns:m.0gzh ns:government.politician.government_positions_held ?pos .
      ?pos ns:government.government_position_held.basic_title ns:m.060c4 ;
           ns:government.government_position_held.from ?pfrom ;
           ns:government.government_position_held.to ?pto .
    }
  }
  {
    SELECT ?from ?to ?conflict
    WHERE {
      ?conflict ns:common.topic.notable_types ns:m.02h76fz .
      ?conflict ns:time.event.start_date ?from .
      ?conflict ns:time.event.end_date ?to .
      ?conflict ns:military.military_conflict.combatants ?combatant .
      ?combatant ns:military.military_combatant_group.combatants ns:m.09c7w0 .
    }
  }
  FILTER (?to <= ?pto && ?from >= ?pfrom)
  BIND (?conflict AS ?war)
}
```

