```sparql
PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?lastGoToSuperBowl ?winYear ?coach1996 WHERE {
  {
    SELECT ?lastGoToSuperBowl WHERE {
      ns:m.02896 ns:sports.sports_championship.events ?event .
      {
        { ?event ns:sports.sports_championship_event.runner_up ns:m.02896 . }
        UNION
        { ?event ns:sports.sports_championship_event.champion ns:m.02896 . }
      }
      ?event ns:time.event.start_date ?lastGoToSuperBowl .
    }
    ORDER BY DESC(?lastGoToSuperBowl)
    LIMIT 1
  }
  {
    SELECT (GROUP_CONCAT(DISTINCT STR(YEAR(?date)); separator=", ") AS ?winYear) WHERE {
      ns:m.02896 ns:sports.sports_team.championships ?champ .
      ?champ ns:sports.sports_championship_event.champion ns:m.02896 .
      ?champ ns:time.event.start_date ?date .
    }
  }
  {
    SELECT ?coach1996 WHERE {
      ns:m.02896 ns:american_football.football_team.historical_coaching_staff ?staff .
      ?staff ns:american_football.football_historical_coach_position.coach ?coach1996 .
      FILTER(
        (NOT EXISTS {?staff ns:american_football.football_historical_coach_position.from ?fromDate} || ?fromDate <= "1996-12-31"^^xsd:dateTime)
        &&
        (NOT EXISTS {?staff ns:american_football.football_historical_coach_position.to ?toDate} || ?toDate >= "1996-01-01"^^xsd:dateTime)
      )
    }
    LIMIT 1
  }
}
```

