```PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?win_year ?last_superbowl ?coach
WHERE {
  # The years Dallas Cowboys won the Super Bowl
  OPTIONAL {
    ns:m.02896 ns:sports.sports_team.championships ?championship .
    FILTER(?championship = ns:m.06x5s) .
    ?championship ns:time.event.start_date ?champ_date .
    BIND(year(xsd:dateTime(?champ_date)) AS ?win_year)
  }
  # The last time Dallas Cowboys went to the Super Bowl
  OPTIONAL {
    ns:m.06x5s ns:sports.sports_championship.events ?sb_event .
    {
      ?sb_event ns:sports.sports_championship_event.runner_up ns:m.02896 .
    } UNION {
      ?sb_event ns:sports.sports_championship_event.champion ns:m.02896 .
    }
    ?sb_event ns:time.event.start_date ?sb_date .
    BIND(xsd:dateTime(?sb_date) AS ?last_superbowl)
  }
  # The coach of Dallas Cowboys in 1996
  OPTIONAL {
    ns:m.02896 ns:american_football.football_team.historical_coaching_staff ?staff .
    ?staff ns:american_football.football_historical_coach_position.coach ?coach .
    FILTER(
      ( !bound(?from) || ( ?from <= "1996-12-31T23:59:59Z"^^xsd:dateTime ) )
      &&
      ( !bound(?to) || ( ?to >= "1996-01-01T00:00:00Z"^^xsd:dateTime ) )
    )
    OPTIONAL { ?staff ns:american_football.football_historical_coach_position.from ?from }
    OPTIONAL { ?staff ns:american_football.football_historical_coach_position.to ?to }
  }
}
ORDER BY DESC(?last_superbowl)
LIMIT 1
