```PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?lastSuperBowl ?winYear ?coach
WHERE {
  {
    # Last time Dallas Cowboys went to the Super Bowl (as champion or runner-up)
    ns:m.02896 ns:sports.sports_team.championships ?championship .
    ?championship ns:sports.sports_championship.events ?lastSuperBowl .
    {
      { ?lastSuperBowl ns:sports.sports_championship_event.champion ns:m.02896 . }
      UNION
      { ?lastSuperBowl ns:sports.sports_championship_event.runner_up ns:m.02896 . }
    }
  }
  OPTIONAL {
    # Years Dallas Cowboys won the Super Bowl
    ns:m.02896 ns:sports.sports_team.championships ?championship2 .
    ?championship2 ns:sports.sports_championship.events ?winEvent .
    ?winEvent ns:sports.sports_championship_event.champion ns:m.02896 .
    ?winEvent ns:time.event.start_date ?winDate .
    BIND(year(xsd:dateTime(?winDate)) AS ?winYear)
  }
  OPTIONAL {
    # Coach of Dallas Cowboys in 1996
    ns:m.02896 ns:american_football.football_team.historical_coaching_staff ?staff .
    ?staff ns:american_football.football_historical_coach_position.coach ?coach .
    FILTER(NOT EXISTS {?staff ns:american_football.football_historical_coach_position.from ?from} || 
           ?from <= "1996-12-31"^^xsd:dateTime)
    FILTER(NOT EXISTS {?staff ns:american_football.football_historical_coach_position.to ?to} || 
           ?to >= "1996-01-01"^^xsd:dateTime)
  }
}
