PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?answer WHERE {
  {
    # Who became president when Roosevelt died in office?
    ns:m.060d2 ns:government.government_office_or_title.office_holders ?pos1 .  # President of the United States
    ?pos1 ns:government.government_position_held.office_holder ns:m.02yy8 ;  # Franklin D. Roosevelt
