    ns:m.060d2 ns:government.government_office_or_title.office_holders ?pos2 .
    ?pos2 ns:government.government_position_held.office_holder ?answer ;
          ns:government.government_position_held.to ?from .

    FILTER(xsd:dateTime(?from) - xsd:dateTime(?to) > 0)
  }
  UNION
  {
    # What did Abraham Lincoln do before he was president?
    {
      SELECT ?pFrom WHERE {
        ns:m.0gzh ns:government.politician.government_positions_held ?posLincoln .
        ?posLincoln ns:government.government_position_held.office_position_or_title ?office ;
                   ns:government.government_position_held.basic_title ns:m.060c4 ;
                   ns:government.government_position_held.from ?pFrom .
      }
    }
    ns:m.0gzh ns:government.politician.government_positions_held ?posBefore .
    ?posBefore ns:government.government_position_held.office_position_or_title ?answer ;
               ns:government.government_position_held.from ?from .

    FILTER(xsd:dateTime(?pFrom) - xsd:dateTime(?from) > 0)
  }
  UNION
  {
    # Who was Theodore Roosevelt's vice president?
    FILTER (?answer != ns:m.07hyk)
    FILTER (!isLiteral(?answer) || lang(?answer) = '' || langMatches(lang(?answer), 'en'))
    ns:m.07hyk ns:government.us_president.vice_president ?answer .
  }
}
